parameters.jsCode:
// Fires the moment a visitor submits the pre-chat phone+email step, before
// the conversation even starts. Independent of whatever the chat itself
// does afterward — this is what actually captures the lead.
const body = $input.first().json.body || {};

const countryCode = String(body.countryCode || '').trim();
const phone = String(body.phone || '').trim();
const email = String(body.email || '').trim();

const validPhone = phone.length >= 6;
const validEmail = /\S+@\S+\.\S+/.test(email);
const isValid = validPhone && validEmail;

return [{
  json: {
    isValid,
    countryCode,
    phone,
    email,
    capturedAt: new Date().toISOString(),
    toEmail: 'sales@openmind.in',
  },
}];

parameters.message:
=A visitor opened the website chatbot and shared their contact details before the conversation started.

Phone: {{ $json.countryCode }} {{ $json.phone }}
Email: {{ $json.email }}
Captured at: {{ $json.capturedAt }}

This is a separate signal from anything Suhani discusses with them in the chat itself — treat it as a lead worth following up even if the conversation doesn't go anywhere.
